#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

const long long INF = 1e18;

struct EdgeInput {
    int u, v, t;
};

struct Edge {
    int to;
    int weight;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m, k;
    if (!(cin >> n >> m >> k)) return 0;

    vector<int> p(k + 1);
    for (int i = 1; i <= k; ++i) {
        cin >> p[i];
    }

    vector<EdgeInput> edges(m);
    vector<vector<pair<int, int>>> station_edges(n + 1);

    for (int i = 0; i < m; ++i) {
        cin >> edges[i].u >> edges[i].v >> edges[i].t;
        station_edges[edges[i].u].push_back({edges[i].t, i});
        station_edges[edges[i].v].push_back({edges[i].t, i});
    }

    int a, b;
    cin >> a >> b;

    int total_nodes = n;
    vector<int> edge_node_u(m);
    vector<int> edge_node_v(m);

    // Grafo para o Dijkstra
    // Vértices 1 a n representam as estações base.
    // Vértices > n representam pares (estação, sistema).
    vector<vector<Edge>> adj;
    adj.resize(n + 1);

    for (int u = 1; u <= n; ++u) {
        auto& elist = station_edges[u];
        sort(elist.begin(), elist.end());

        for (size_t i = 0; i < elist.size(); ) {
            size_t j = i;
            int type = elist[i].first;
            total_nodes++;
            adj.emplace_back(); // total_nodes index

            int aux = total_nodes;

            // Da estação base u para aux com custo p[type]
            adj[u].push_back({aux, p[type]});
            // De aux para a estação base u com custo 0
            adj[aux].push_back({u, 0});

            while (j < elist.size() && elist[j].first == type) {
                int edge_idx = elist[j].second;
                if (edges[edge_idx].u == u) {
                    edge_node_u[edge_idx] = aux;
                } else {
                    edge_node_v[edge_idx] = aux;
                }
                j++;
            }
            i = j;
        }
    }

    // Adiciona as arestas de custo 0 entre os nós dos sistemas
    for (int i = 0; i < m; ++i) {
        int u_node = edge_node_u[i];
        int v_node = edge_node_v[i];
        adj[u_node].push_back({v_node, 0});
        adj[v_node].push_back({u_node, 0});
    }

    // Dijkstra a partir de A
    vector<long long> dist(total_nodes + 1, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;

    dist[a] = 0;
    pq.push({0, a});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (d > dist[u]) continue;
        if (u == b) break;

        for (const auto& edge : adj[u]) {
            if (dist[u] + edge.weight < dist[edge.to]) {
                dist[edge.to] = dist[u] + edge.weight;
                pq.push({dist[edge.to], edge.to});
            }
        }
    }

    if (dist[b] == INF) {
        cout << -1 << "\n";
    } else {
        cout << dist[b] << "\n";
    }

    return 0;
}
